<template>
  <el-dialog v-model="visible" :title="editingTask ? '编辑自动化' : selectedTemplate ? `新建自动化 · 来自模板「${selectedTemplate.name}」` : '新建自动化'" width="min(760px, calc(100vw - 48px))" top="6vh" class="automation-wizard" destroy-on-close @closed="$emit('closed')">
    <TemplatePicker v-if="showTemplates" @skip="beginBlank" @select="beginTemplate" />
    <template v-else>
      <div class="wizard-steps"><div v-for="(label, index) in stepLabels" :key="label" class="wizard-step" :class="{ active: step === index + 1, done: step > index + 1 }"><span>{{ step > index + 1 ? '✓' : index + 1 }}</span><b>{{ label }}</b><i v-if="index < stepLabels.length - 1" aria-hidden="true" /></div></div>
      <section v-if="step === 1" class="wizard-section"><header><h3>先说说要做什么</h3><p>只需要描述任务内容，名称可以留空，保存时会自动生成。</p></header><el-form label-position="top"><el-form-item label="任务名称"><el-input v-model="form.name" maxlength="80" placeholder="例如：每日项目进展总结" /><p v-if="suggestedName" class="suggestion"><AppIcon name="MagicStick" />根据 Prompt 建议：<button type="button" @click="form.name = suggestedName">使用“{{ suggestedName }}”</button></p></el-form-item><el-form-item label="任务 Prompt" required><el-input v-model="form.prompt" type="textarea" :rows="7" maxlength="6000" show-word-limit placeholder="描述每次触发后需要 Mira 完成的工作。支持 {{项目}}、{{日期}} 等变量。" /></el-form-item></el-form></section>
      <section v-else-if="step === 2" class="wizard-section"><header><h3>什么时候运行</h3><p>选择频率后会自动生成底层调度，并在保存前显示下一次运行时间。</p></header><SchedulePicker v-model="form.trigger" @validity-change="scheduleValid = $event" /></section>
      <section v-else class="wizard-section"><header><h3>运行设置</h3><p>默认设置适合大多数任务，也可以按项目需要调整。</p></header><el-form class="setup-form" label-position="top"><div class="setup-columns"><div><el-form-item label="目标项目" required><el-select v-model="form.projectId" filterable placeholder="选择项目" @change="form.sessionId = ''"><el-option v-for="project in projects" :key="project.id" :label="project.name" :value="project.id" /></el-select></el-form-item><el-form-item label="模型" required><el-select v-model="form.modelKey" filterable placeholder="选择已配置模型"><el-option v-for="model in modelOptions" :key="model.key" :label="model.modelId" :value="model.key" /></el-select><p v-if="!modelOptions.length" class="form-tip form-tip--warning">还没有可用模型，请先到 <button type="button" class="inline-link" @click="goModelConfig">系统管理 → 模型配置</button> 完成配置。</p></el-form-item><el-form-item label="有效期"><div class="validity-row"><el-switch v-model="form.validityEnabled" /><span>仅在指定时间内运行</span><el-date-picker v-if="form.validityEnabled" v-model="form.validFrom" type="datetime" value-format="x" placeholder="生效时间" /><el-date-picker v-if="form.validityEnabled" v-model="form.validUntil" type="datetime" value-format="x" placeholder="失效时间" /></div><p class="form-tip">到期后任务自动结束，适合临时任务。</p></el-form-item></div><div><el-form-item label="运行于" required><el-radio-group v-model="form.targetType" @change="form.sessionId = ''"><el-radio-button value="new-session">新聊天</el-radio-button><el-radio-button value="existing-session" :disabled="form.trigger.type === 'session-completed'">现有聊天</el-radio-button></el-radio-group><p class="form-tip">{{ form.trigger.type === 'session-completed' ? '人工会话完成任务会写入触发聊天。' : form.targetType === 'new-session' ? '每次运行创建独立聊天，避免混入人工上下文。' : '仅在该聊天空闲时运行。' }}</p></el-form-item><el-form-item v-if="form.targetType === 'existing-session'" label="现有聊天" required><el-select v-model="form.sessionId" filterable fit-input-width popper-class="automation-session-select-popper" placeholder="选择当前项目的聊天"><el-option v-for="session in projectSessions" :key="session.id" :label="session.title" :value="session.id"><span :title="session.title">{{ session.title }}</span></el-option></el-select></el-form-item><el-form-item label="权限" required><el-radio-group v-model="form.permissionMode"><el-radio-button value="full" :disabled="!permissionConfig.fullAccessEnabled">完全访问（推荐）</el-radio-button><el-radio-button value="auto-approve" :disabled="!permissionConfig.autoApproveEnabled">自动审核</el-radio-button></el-radio-group><p class="form-tip">{{ permissionHint }}</p></el-form-item></div></div></el-form></section>
    </template>
    <template #footer><div v-if="!showTemplates" class="wizard-footer"><el-button :style="{ visibility: step === 1 ? 'hidden' : 'visible' }" @click="step -= 1">上一步</el-button><div><el-button @click="visible = false">取消</el-button><el-button v-if="step < 3" type="primary" :disabled="!canNext" @click="step += 1">下一步<AppIcon name="ArrowRight" /></el-button><el-button v-else type="primary" :loading="saving" :disabled="!canSave" @click="save">保存任务</el-button></div></div></template>
  </el-dialog>
</template>

<script setup lang="ts">
import { computed, reactive, ref, watch } from 'vue'
import { ElMessage } from 'element-plus'
import { useRouter } from 'vue-router'
import type { AutomationTask, AutomationTaskInput, AutomationTrigger, HarnessProject, HarnessSessionSummary, ModelProviderSummary, PermissionConfig, PermissionMode } from '@/config/harness'
import { DEFAULT_PERMISSION_CONFIG } from '@/config/harness'
import { getPlatformApi } from '@/platform'
import TemplatePicker from './TemplatePicker.vue'
import SchedulePicker from './SchedulePicker.vue'
import type { AutomationTemplate } from '../automationTemplates'

const props = defineProps<{ modelValue: boolean, projects: HarnessProject[], sessions: HarnessSessionSummary[], providers: ModelProviderSummary[], permissionConfig: PermissionConfig, editingTask?: AutomationTask, startWithTemplates: boolean }>()
const emit = defineEmits<{ 'update:modelValue': [value: boolean], saved: [], closed: [] }>()
const router = useRouter(); const visible = ref(props.modelValue); const step = ref(1); const showTemplates = ref(false); const selectedTemplate = ref<AutomationTemplate>(); const saving = ref(false); const scheduleValid = ref(true)
const form = reactive({ name: '', prompt: '', projectId: '', trigger: { type: 'cron', expression: '0 9 * * 1-5', humanLabel: '每个工作日 09:00' } as AutomationTrigger, targetType: 'new-session' as 'new-session' | 'existing-session', sessionId: '', modelKey: '', permissionMode: 'full' as PermissionMode, validityEnabled: false, validFrom: undefined as string | undefined, validUntil: undefined as string | undefined })
const stepLabels = ['任务内容', '触发方式', '运行设置']
const permissionConfig = computed(() => props.permissionConfig || DEFAULT_PERMISSION_CONFIG)
const projectSessions = computed(() => props.sessions.filter(session => session.projectId === form.projectId))
const modelOptions = computed(() => props.providers.filter(provider => provider.enabled && provider.hasApiKey).flatMap(provider => provider.models.map(modelId => ({ key: `${provider.id}:${modelId}`, modelId }))))
const selectedModel = computed(() => { const [providerId, ...model] = form.modelKey.split(':'); return providerId && model.length ? { providerId, modelId: model.join(':') } : undefined })
const suggestedName = computed(() => form.prompt.trim().replace(/\s+/g, ' ').slice(0, 20).replace(/[，。！？,.!?]+$/, ''))
const permissionHint = computed(() => form.permissionMode === 'full' ? '完全访问：允许Mira在无人值守任务中自动执行操作，可能涉及敏感数据或者文件修改，仅在信任任务时使用，用户可随时恢复默认权限。' : '自动审核：敏感操作需要用户确认。如果你离开屏幕，任务会停在等待状态，仅推荐在本地调试/手动监管时使用。')
const canNext = computed(() => step.value === 1 ? Boolean(form.prompt.trim()) : scheduleValid.value)
const canSave = computed(() => Boolean(form.prompt.trim() && form.projectId && selectedModel.value && scheduleValid.value && (form.targetType === 'new-session' || form.sessionId) && (!form.validityEnabled || form.validUntil)))

watch(() => props.modelValue, value => { visible.value = value; if (value) open() }); watch(visible, value => emit('update:modelValue', value))
function defaultProject() { return props.projects[0]?.id || '' }
function defaultModel() { const binding = props.providers.find(provider => provider.enabled && provider.hasApiKey && provider.models.length); return binding ? `${binding.id}:${binding.models[0]}` : '' }
function reset() { Object.assign(form, { name: '', prompt: '', projectId: defaultProject(), trigger: { type: 'cron', expression: '0 9 * * 1-5', humanLabel: '每个工作日 09:00' }, targetType: 'new-session', sessionId: '', modelKey: defaultModel(), permissionMode: 'full', validityEnabled: false, validFrom: undefined, validUntil: undefined }); step.value = 1; scheduleValid.value = true }
function open() { reset(); showTemplates.value = !props.editingTask && props.startWithTemplates; selectedTemplate.value = undefined; if (props.editingTask) loadTask(props.editingTask) }
function loadTask(task: AutomationTask) { Object.assign(form, { name: task.name, prompt: task.prompt, projectId: task.projectId, trigger: { ...task.trigger }, targetType: task.target.type, sessionId: task.target.type === 'existing-session' ? task.target.sessionId : '', modelKey: `${task.model.providerId}:${task.model.modelId}`, permissionMode: task.permissionMode === 'default' ? 'full' : task.permissionMode, validityEnabled: Boolean(task.validFrom || task.validUntil), validFrom: task.validFrom ? String(task.validFrom) : undefined, validUntil: task.validUntil ? String(task.validUntil) : undefined }); showTemplates.value = false }
function beginBlank() { showTemplates.value = false; reset() }
function beginTemplate(template: AutomationTemplate) { selectedTemplate.value = template; showTemplates.value = false; form.name = template.name; form.prompt = template.prompt; form.trigger = { ...template.trigger }; if (template.trigger.type === 'session-completed') form.targetType = 'new-session'; step.value = 1 }
function goModelConfig() { visible.value = false; void router.push({ name: 'SettingsModelConfig' }) }
function plainTrigger(trigger: AutomationTrigger): AutomationTrigger { return trigger.type === 'once' ? { type: 'once', scheduledAt: trigger.scheduledAt } : trigger.type === 'cron' ? { type: 'cron', expression: trigger.expression, ...(trigger.humanLabel ? { humanLabel: trigger.humanLabel } : {}) } : { type: 'session-completed' } }
async function save() { const api = getPlatformApi(); if (!api || !canSave.value || !selectedModel.value) return; saving.value = true; try { const trigger = plainTrigger(form.trigger); const input: AutomationTaskInput = { ...(props.editingTask ? { id: props.editingTask.id } : {}), name: form.name.trim() || suggestedName.value, projectId: form.projectId, trigger, target: trigger.type === 'session-completed' || form.targetType === 'new-session' ? { type: 'new-session' } : { type: 'existing-session', sessionId: form.sessionId }, prompt: form.prompt, model: { ...selectedModel.value }, permissionMode: form.permissionMode, ...(selectedTemplate.value ? { templateId: selectedTemplate.value.id } : {}), ...(form.validityEnabled ? { ...(form.validFrom ? { validFrom: Number(form.validFrom) } : {}), ...(form.validUntil ? { validUntil: Number(form.validUntil) } : {}) } : {}) }; await api.saveAutomationTask(input); visible.value = false; ElMessage.success(props.editingTask ? '自动化任务已更新' : '自动化任务已创建'); emit('saved') } catch (cause) { ElMessage.error(cause instanceof Error ? cause.message : '保存自动化失败') } finally { saving.value = false } }
</script>

<style scoped lang="scss">
 .automation-wizard :deep(.el-dialog__header) { margin: 0; padding: 20px 24px 12px; border-bottom: 1px solid var(--cp-border-light); }.automation-wizard :deep(.el-dialog__title) { color: var(--cp-text); font-size: 18px; font-weight: 600; }.automation-wizard :deep(.el-dialog__body) { padding: 0 24px 12px; }.automation-wizard :deep(.el-dialog__footer) { padding: 0 24px 18px; border-top: 0; }.wizard-steps { display: flex; gap: 0; padding: 3px 0 22px; }.wizard-step { display: flex; min-width: 0; flex: 1; align-items: center; gap: 8px; color: var(--cp-text-tertiary); font-size: 13px; }.wizard-step span { display: grid; width: 28px; height: 28px; flex: 0 0 28px; place-items: center; border-radius: 50%; color: var(--cp-text-secondary); background: var(--cp-border-light); font-size: 12px; font-weight: 600; }.wizard-step b { flex: 0 0 auto; white-space: nowrap; }.wizard-step i { height: 1px; min-width: 12px; flex: 1; margin-right: 14px; background: var(--cp-border); }.wizard-step.done i { background: var(--cp-primary); }.wizard-step.active { color: var(--cp-text); font-weight: 600; }.wizard-step.active span { color: var(--cp-primary-contrast, #fff); background: var(--cp-primary); box-shadow: 0 0 0 4px var(--cp-primary-lighter); }.wizard-step.done { color: var(--cp-primary); }.wizard-step.done span { color: var(--cp-primary); background: var(--cp-primary-lighter); }.wizard-section { min-height: 390px; padding: 4px 0 10px; }.wizard-section header { margin-bottom: 22px; }.wizard-section h3 { margin: 0; color: var(--cp-text); font-size: 17px; font-weight: 600; }.wizard-section header p { margin: 5px 0 0; color: var(--cp-text-secondary); font-size: 13px; }.wizard-section > :deep(.el-form) :deep(.el-select), .wizard-section > :deep(.el-form) :deep(.el-date-editor) { width: 100%; }.wizard-section :deep(.el-form-item) { margin-bottom: 19px; }.setup-columns { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); column-gap: 24px; }.setup-columns > div { min-width: 0; }.suggestion { display: flex; align-items: center; gap: 5px; margin: 7px 0 0; color: var(--cp-text-tertiary); font-size: 12px; }.suggestion .app-icon { color: var(--cp-primary); }.suggestion button, .inline-link { padding: 0; border: 0; color: var(--cp-primary); background: transparent; font: inherit; cursor: pointer; }.form-tip { margin: 7px 0 0; color: var(--cp-text-secondary); font-size: 12px; line-height: 1.5; }.form-tip--warning { color: var(--cp-warning); }.validity-row { display: flex; align-items: center; flex-wrap: wrap; gap: 8px; color: var(--cp-text-secondary); font-size: 13px; }.validity-row :deep(.el-date-editor) { width: 210px !important; }.wizard-footer { display: flex; align-items: center; justify-content: space-between; gap: 8px; }.wizard-footer > div { display: flex; gap: 8px; }.wizard-footer :deep(.app-icon) { margin-left: 4px; }:global(.automation-session-select-popper.el-popper) { width: 352px !important; min-width: 0 !important; max-width: calc(100vw - 48px); }:global(.automation-session-select-popper .el-select-dropdown__item), :global(.automation-session-select-popper .el-select-dropdown__item > span) { display: block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
</style>
